#   덩어리 위계: 머리카락 한 덩어리 · 코트 한 덩어리(끝 2~3개) · 흰 셔츠/코트 넓게 · 강조색 작은 자리만
from mass import *

def legs(F, g, hip, knee, ankle, toe, thick=1.0):
    F.ribbon(g, [hip, lerp(hip, knee, 0.45), knee], [0.15 * thick, 0.125 * thick, 0.072 * thick], 8)
    calf = lerp(knee, ankle, 0.3); calf = (calf[0], calf[1], calf[2] - 0.015)
    F.ribbon(g, [knee, calf, lerp(knee, ankle, 0.75), ankle], [0.072 * thick, 0.084 * thick, 0.055 * thick, 0.04 * thick], 8)
    F.ribbon(g, [add(ankle, (0, 0.02, -0.02)), lerp(ankle, toe, 0.5), toe], [0.06 * thick, 0.05 * thick, 0.0], 6)

def hand(F, g, wrist, d, L=0.1, open_=0.4):
    F.ribbon(g, [wrist, add(wrist, (d[0] * 0.04, d[1] * 0.04, d[2] * 0.04))], [0.05, 0.055], 4)
    base = add(wrist, (d[0] * 0.045, d[1] * 0.045, d[2] * 0.045))
    for k in range(4):
        o = (k - 1.5) * 0.012
        F.ribbon(g, [base, add(base, (d[0] * L * 0.5 + o * (1 + open_), d[1] * L * 0.5, d[2] * L * 0.5)), add(base, (d[0] * L * (0.9 + 0.05 * (k % 2)) + o * (1.5 + open_), d[1] * L * (0.95 - 0.04 * abs(k - 1.5)), d[2] * L))], [0.017, 0.014, 0.0], 5)

